package org.example.behavioral_pattern.strategy_pattern.spring_boot.impl;import org.example.behavioral_pattern.strategy_pattern.spring_boot.ShippingStrategy;import org.example.behavioral_pattern.strategy_pattern.delivery.EShippingType;import org.example.behavioral_pattern.strategy_pattern.delivery.Order;import org.springframework.stereotype.Component;@Componentpublic class SameDayShippingStrategy implements ShippingStrategy {    public EShippingType getType() {        return EShippingType.SAME_DAY;    }    public int calculateFee(Order order) {        return order.getWeightInGram() > 1000 ? 120 : 100;    }}